// contact details: one list edited from the resume and the catalog builder, shown per document
const {chromium}=require('playwright');const path=require('path');
const ok=(c,m)=>{console.log((c?'PASS ':'FAIL ')+m);if(!c)process.exitCode=1};
(async()=>{const app=path.resolve(process.argv[2]);const b=await chromium.launch();const p=await b.newPage({viewport:{width:1366,height:900}});const errs=[];p.on('pageerror',e=>errs.push(e.message));p.on('dialog',d=>d.accept());
const w=ms=>p.waitForTimeout(ms);const as=async u=>{await p.evaluate(u=>{ME=S.users.find(x=>x.user===u);permBump();rerender()},u);await w(200)};
const cvTxt=()=>p.evaluate(()=>cvContact());const catTxt=()=>p.evaluate(()=>cbContact());
await p.goto('file://'+app+'#/');await p.waitForFunction(()=>window.__KS_OK);await as('admin');
await p.goto('file://'+app+'#/admin/resume');await w(500);
ok(await p.$('#cted .ct-row'),'contact editor on the resume page');
const row=i=>`#cted .ct-row[data-ct="${i}"]`;
await p.fill(row(0)+' [data-cf2=v]','تهران، خیابان آزمون، پلاک ۱');await p.dispatchEvent(row(0)+' [data-cf2=v]','change');await w(200);
ok((await cvTxt()).includes('خیابان آزمون')&&(await catTxt()).includes('خیابان آزمون'),'new office address in the resume and on the catalog back cover');
ok(await p.evaluate(()=>BIZ.addr.includes('خیابان آزمون')),'print footers follow (BIZ.addr)');
await p.uncheck(row(1)+' [data-cf2=cat]');await w(200);
ok((await cvTxt()).includes('میدان قزوین')&&!(await catTxt()).includes('میدان قزوین'),'branch hidden on the catalog only');
await p.goto('file://'+app+'#/admin/catalog');await w(600);ok(await p.$('#cted'),'same editor in the catalog builder');
await p.click('#ctadd');await w(300);const n=await p.evaluate(()=>ctRows().length-1);
await p.selectOption(`#cted .ct-row[data-ct="${n}"] [data-cf2=k]`,'email');await w(300);
await p.fill(`#cted .ct-row[data-ct="${n}"] [data-cf2=l]`,'ایمیل');await p.fill(`#cted .ct-row[data-ct="${n}"] [data-cf2=v]`,'info@karma.ir');await w(200);
ok((await cvTxt()).includes('info@karma.ir')&&(await catTxt()).includes('info@karma.ir'),'email row added from the catalog builder shows in both');
await p.fill(`#cted .ct-row[data-ct="2"] [data-cf2=v]`,'021-11112222، 021-33334444، 021-55556666');await w(200);
const tl=await p.evaluate(()=>JSON.stringify([BIZ.tels,ctRows().map(r=>r.id+':'+r.k)]));ok(await p.evaluate(()=>BIZ.tels.length===3)&&(await catTxt()).includes('021-55556666'),'three phone numbers '+tl);
await p.goto('file://'+app+'#/doc/cat');await w(1500);ok((await p.textContent('.cx-back')).includes('info@karma.ir'),'back cover of the printed catalog');
await p.goto('file://'+app+'#/doc/cv');await w(1200);ok((await p.textContent('#app')).includes('خیابان آزمون'),'printed resume');
await as('sales');await p.goto('file://'+app+'#/admin/resume');await w(400);
await as('product');await p.goto('file://'+app+'#/admin/catalog');await w(500);ok(!(await p.$eval('#cted [data-cf2=v]',e=>e.disabled)),'product role can edit');
await p.evaluate(()=>{const u=S.users.find(x=>x.user==='product');u.deny=['company.resume.edit'];permBump()});await p.evaluate(()=>rerender());await w(500);
ok(await p.$eval('#cted [data-cf2=v]',e=>e.disabled),'without resume edit permission the list is read-only');
ok(!errs.length,'no JS errors '+errs.slice(0,3));await b.close()})();
